import os
import sys
import select
from array import array

try:
    import termios
except ImportError:
    termios = None

try:
    import fcntl
except ImportError:
    fcntl = None

class ReadKeyRaw:
    _ESCAPE_MAP = {
        # Function keys
        "OP": "#f1", "OQ": "#f2", "OR": "#f3", "OS": "#f4",
        "[15~": "#f5", "[17~": "#f6", "[18~": "#f7", "[19~": "#f8",
        "[20~": "#f9", "[21~": "#f10", "[23~": "#f11", "[24~": "#f12",
        # Shifted function keys
        "[1;2P": "#F1", "[1;2Q": "#F2", "[1;2R": "#F3", "[1;2S": "#F4",
        "[15;2~": "#F5", "[17;2~": "#F6", "[18;2~": "#F7", "[19;2~": "#F8",
        "[20;2~": "#F9", "[21;2~": "#F10", "[23;2~": "#F11", "[24;2~": "#F12",
        # Control function keys
        "[1;5P": "#C-f1", "[1;5Q": "#C-f2", "[1;5R": "#C-f3", "[1;5S": "#C-f4",
        "[15;5~": "#C-f5", "[17;5~": "#C-f6", "[18;5~": "#C-f7", "[19;5~": "#C-f8",
        "[20;5~": "#C-f9", "[21;5~": "#C-f10", "[23;5~": "#C-f11", "[24;5~": "#C-f12",
        # Control+Shift function keys
        "[1;6P": "#C-F1", "[1;6Q": "#C-F2", "[1;6R": "#C-F3", "[1;6S": "#C-F4",
        "[15;6~": "#C-F5", "[17;6~": "#C-F6", "[18;6~": "#C-F7", "[19;6~": "#C-F8",
        "[20;6~": "#C-F9", "[21;6~": "#C-F10", "[23;6~": "#C-F11", "[24;6~": "#C-F12",
        # Alt function keys
        "[1;3P": "#A-f1", "[1;3Q": "#A-f2", "[1;3R": "#A-f3", "[1;3S": "#A-f4",
        "[15;3~": "#A-f5", "[17;3~": "#A-f6", "[18;3~": "#A-f7", "[19;3~": "#A-f8",
        "[20;3~": "#A-f9", "[21;3~": "#A-f10", "[23;3~": "#A-f11", "[24;3~": "#A-f12",
        # Alt+Shift function keys
        "[1;4P": "#A-F1", "[1;4Q": "#A-F2", "[1;4R": "#A-F3", "[1;4S": "#A-F4",
        "[15;4~": "#A-F5", "[17;4~": "#A-F6", "[18;4~": "#A-F7", "[19;4~": "#A-F8",
        "[20;4~": "#A-F9", "[21;4~": "#A-F10", "[23;4~": "#A-F11", "[24;4~": "#A-F12",
        # Alt+Control function keys
        "[1;7P": "#AC-f1", "[1;7Q": "#AC-f2", "[1;7R": "#AC-f3", "[1;7S": "#AC-f4",
        "[15;7~": "#AC-f5", "[17;7~": "#AC-f6", "[18;7~": "#AC-f7", "[19;7~": "#AC-f8",
        "[20;7~": "#AC-f9", "[21;7~": "#AC-f10", "[23;7~": "#AC-f11", "[24;7~": "#AC-f12",
        # Alt+Control+Shift function keys
        "[1;8P": "#AC-F1", "[1;8Q": "#AC-F2", "[1;8R": "#AC-F3", "[1;8S": "#AC-F4",
        "[15;8~": "#AC-F5", "[17;8~": "#AC-F6", "[18;8~": "#AC-F7", "[19;8~": "#AC-F8",
        "[20;8~": "#AC-F9", "[21;8~": "#AC-F10", "[23;8~": "#AC-F11", "[24;8~": "#AC-F12",
        # Cursor keys
        "[A": "#UP", "[B": "#DN", "[C": "#RT", "[D": "#LT", "[H": "#HOM",
        "[F": "#END", "[2~": "#INS", "[3~": "#DEL", "[5~": "#PUP", "[6~": "#PDN",
        # macOS cursor key differences
        "OH": "#HOM", "OF": "#END",
        # Alt cursor keys
        "[1;3A": "#A-UP", "[1;3B": "#A-DN", "[1;3C": "#A-RT", "[1;3D": "#A-LT",
        "[1;3H": "#A-HOM", "[1;3F": "#A-END", "[2;3~": "#A-INS", "[3;3~": "#A-DEL",
        "[5;3~": "#A-PUP", "[6;3~": "#A-PDN",
        # Control cursor keys
        "[1;5A": "#C-UP", "[1;5B": "#C-DN", "[1;5C": "#C-RT", "[1;5D": "#C-LT",
        "[1;5H": "#C-HOM", "[1;5F": "#C-END", "[2;5~": "#C-INS", "[3;5~": "#C-DEL",
        "[5;5~": "#C-PUP", "[6;5~": "#C-PDN",
    }

    def __init__(self):
        self._fd = None
        self._old_settings = None
        self._debug = False

    def _require_fd(self):
        if self._fd is None:
            raise RuntimeError("ReadKeyRaw must be used as a context manager before reading keys")
        return self._fd

    def __enter__(self):
        self._fd = sys.stdin.fileno()
        if os.name != "nt" and termios is not None:
            self._old_settings = termios.tcgetattr(self._fd)
            new_settings = termios.tcgetattr(self._fd)
            new_settings[3] &= ~(termios.ICANON | termios.ECHO)
            termios.tcsetattr(self._fd, termios.TCSADRAIN, new_settings)
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if os.name != "nt" and termios is not None and self._old_settings is not None:
            termios.tcsetattr(self._require_fd(), termios.TCSADRAIN, self._old_settings)

    def set_debug(self, debug):
        """Enable or disable debug output"""
        self._debug = debug

    def read_key(self):
        """Read one key and return it in Bash-compatible symbolic form."""
        return self.read_key_raw()

    def read_key_raw(self, timeout=None):
        """Read one keypress and return literals.

        Returns values like '#UP', '#TAB', '#ESC', '#C-X', '#TIMEOUT',
        and translated function-key identifiers.
        """
        sys.stdout.flush()

        if os.name == "nt":
            raw = self.read_key_nt(timeout=timeout)
            return self._translate_windows_result(raw)

        first = self._read_one_byte(timeout=timeout)
        if first is None:
            return "#TIMEOUT"

        if first in (0x08, 0x7F):
            return "#BS"
        if first == 0x0A:
            return "#LF"
        if first == 0x09:
            return "#TAB"

        if first == 0x1B:
            seq = self._collect_escape_suffix()
            if not seq:
                return "#ESC"
            translated = self._translate_escape(seq)
            if self._debug:
                print(f"Escape sequence read: {seq.encode()} => {translated}")
            return translated

        if 0xC2 <= first <= 0xF4:
            expected = 1 if first <= 0xDF else 2 if first <= 0xEF else 3
            data = bytes([first]) + self._read_following_bytes(expected)
            try:
                return data.decode("utf-8")
            except UnicodeDecodeError:
                return data.decode("latin-1", errors="ignore")

        if 1 <= first <= 26:
            return f"#C-{chr(first + 64)}"

        return chr(first)

    def read_key_nt(self, timeout=None):
        """Read a single keypress (raw mode, no echo) (Windows version)
           Translates special keys into the same escape sequences as
           the Linux/Mac version for consistency."""
        import msvcrt

        if timeout is not None:
            if timeout <= 0 and not getattr(msvcrt, "kbhit")():
                return None
            if timeout > 0:
                import time
                end = time.monotonic() + timeout
                while not getattr(msvcrt, "kbhit")():
                    if time.monotonic() >= end:
                        return None
                    time.sleep(0.005)

        ch = msvcrt.getwch()        # type: ignore

        # On Windows consoles, special keys are two-part sequences:
        # prefix (\x00 or \xe0) + a key code.
        if ch in ("\x00", "\xe0"):
            code = msvcrt.getwch()  # type: ignore
            mapping = {
                "K": "[D",          # Left arrow
                "M": "[C",          # Right arrow
                "H": "[A",          # Up arrow
                "P": "[B",          # Down arrow
                "G": "[1~",         # Home
                "O": "[4~",         # End
                "Z": "[Z",          # Shift+Tab (some terminals)
                "\x0f": "[Z",       # Shift+Tab (Windows console code)
                "S": "[3~",         # Delete
                "\x08": "\x7f",     # Backspace (some terminals)
            }
            ch = mapping.get(code, code)
            if self._debug:
                print(f"Special key read: {ch.encode()}") # type: ignore
            return ch

        if self._debug:
            print(f"Character read: {ch.encode()}")
        return ch

    def bytes_waiting(self):
        """Return the number of bytes currently queued for this tty fd.
           Called by read_key_raw() to consume any pending bytes of an
           escape sequence.
        """
        if os.name == "nt" or termios is None or fcntl is None:
            return 0

        fionread = getattr(termios, "FIONREAD", None)
        if fionread is None:
            return 0

        buf = array("I", [0])
        try:
            fcntl.ioctl(self._require_fd(), fionread, buf, True)  # type: ignore[arg-type]
        except OSError:
            return 0
        return int(buf[0])

    def _read_one_byte(self, timeout=None):
        fd = self._require_fd()
        if timeout is not None:
            ready, _, _ = select.select([fd], [], [], max(timeout, 0))
            if not ready:
                return None
        data = os.read(fd, 1)
        if not data:
            return None
        return data[0]

    def _read_following_bytes(self, count):
        fd = self._require_fd()
        out = bytearray()
        for _ in range(count):
            ready, _, _ = select.select([fd], [], [], 0.01)
            if not ready:
                break
            nxt = os.read(fd, 1)
            if not nxt:
                break
            out.extend(nxt)
        return bytes(out)

    def _collect_escape_suffix(self):
        fd = self._require_fd()
        seq = []
        while True:
            pending = self.bytes_waiting()
            if pending == 0:
                ready, _, _ = select.select([fd], [], [], 0.02)
                if not ready:
                    break
                pending = max(self.bytes_waiting(), 1)

            chunk = os.read(fd, pending)
            if not chunk:
                break

            if b"\x1b" in chunk:
                chunk = chunk.split(b"\x1b", 1)[0]
            seq.append(chunk.decode("latin-1", errors="ignore"))

            if not chunk or sum(len(part) for part in seq) >= 32:
                break

        return "".join(seq)

    def _translate_escape(self, seq):
        if seq in self._ESCAPE_MAP:
            return self._ESCAPE_MAP[seq]
        if len(seq) == 1 and "!" <= seq <= "~":
            return f"#A-{seq}"
        return seq

    def _translate_windows_result(self, raw):
        if raw is None:
            return "#TIMEOUT"
        if raw in ("\x08", "\x7f"):
            return "#BS"
        if raw == "\n":
            return "#LF"
        if raw == "\t":
            return "#TAB"
        if raw.startswith("[") or raw.startswith("O"):
            return self._translate_escape(raw)
        if len(raw) == 1 and 1 <= ord(raw) <= 26:
            return f"#C-{chr(ord(raw) + 64)}"
        return raw
